import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { peopleKey, type Person } from '../people/usePeople';
import { useRowAction } from '../people/useRowAction';
import { sheetKey } from '../sheet/useSheet';

/**
 * Transferring a person to another sheet: that sheet's id and the button to transfer. Only a steward
 * may; the server refuses a retired person, this sheet's own id, and a name, alias or contact already
 * on the other sheet. The person arrives there with their grades, terms, contact, aliases and claims,
 * and leaves this list.
 */
function PersonTransfer({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const [to, setTo] = useState('');
  const transfer = useMutation({
    mutationFn: (toSheet: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/transfer`, { to: toSheet, user }),
    // Everything else on both sheets first (the claims move with the person), then the list the row leaves.
    onSuccess: (_data, toSheet) => {
      void queryClient.invalidateQueries({ queryKey: sheetKey(toSheet.trim()) });
      return queryClient.invalidateQueries({
        queryKey: sheetKey(sheet),
        predicate: (q) => q.queryKey[2] !== peopleKey(sheet)[2],
      });
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  const actionTaken = useRowAction(sheet, person.id, transfer.reset);
  return (
    <td>
      <input
        data-testid="person-transfer-to"
        placeholder="Sheet id"
        value={to}
        onChange={(e) => {
          transfer.reset();
          setTo(e.target.value);
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-transfer"
        disabled={transfer.isPending}
        onClick={() => {
          actionTaken();
          transfer.reset();
          transfer.mutate(to);
        }}
      >
        Transfer
      </button>
      {transfer.isError && (
        <span data-testid="person-error" role="alert">
          {' '}
          Could not transfer this person (a steward only, to another sheet, not retired, no name, alias or
          contact already there).
        </span>
      )}
    </td>
  );
}

/** The sheet a transferred person came from; nothing for anyone else. */
function PersonOrigin({ person }: { user: string; sheet: string; person: Person }) {
  return <td data-testid="person-origin">{person.origin ?? ''}</td>;
}

export const contributions = [
  PersonColumns.fill({ order: 45.5, Component: () => <th>From</th> }),
  PersonCells.fill({ order: 45.5, Component: PersonOrigin }),
  PersonColumns.fill({ order: 46, Component: () => <th>Transfer</th> }),
  PersonCells.fill({ order: 46, Component: PersonTransfer }),
];
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
