package net.officefloor.hq.app.sheet;

import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The clone just made, as the screen sees a sheet. */
public class RespondWithClone {
    public void respond(@PathVariable("sheetId") String sheetId, net.officefloor.plugin.variable.@net.officefloor.plugin.variable.Val Clone clone,
            Sheets sheets, ObjectResponse<SheetResponse> response) {
        response.send(new SheetResponse(clone.to(), sheets.today(clone.to()).toString(), sheets.archived(clone.to())));
    }
}
